// Minimal reimplementation of Python's argparse behavior (subset needed here),
// matching its usage/error/help text and exit codes.
import { basename } from 'node:path';

export class ArgumentParser {
  constructor({ prog = null } = {}) {
    // argparse defaults prog to basename(sys.argv[0]); the Node equivalent is
    // the entry script path in process.argv[1].
    this.prog = prog ?? basename(process.argv[1] ?? 'prog');
    this._optionals = [];
    // Built-in -h/--help, added first like argparse does.
    this._optionals.push({
      flags: ['-h', '--help'],
      dest: 'help',
      isHelp: true,
      required: false,
      metavar: null,
      help: 'show this help message and exit',
    });
  }

  addArgument(flags, { required = false, type = 'string', metavar = null } = {}) {
    const flagList = Array.isArray(flags) ? flags : [flags];
    const long = flagList.find((f) => f.startsWith('--')) ?? flagList[0];
    const dest = long.replace(/^-+/, '').replace(/-/g, '_');
    this._optionals.push({
      flags: flagList,
      dest,
      isHelp: false,
      required,
      type,
      metavar: metavar ?? dest.toUpperCase(),
      help: null,
    });
  }

  _formatUsage() {
    const parts = [];
    for (const opt of this._optionals) {
      const flag = opt.flags[0];
      if (opt.isHelp) {
        parts.push(`[${flag}]`);
      } else if (opt.required) {
        parts.push(`${flag} ${opt.metavar}`);
      } else {
        parts.push(`[${flag} ${opt.metavar}]`);
      }
    }
    return `usage: ${this.prog} ${parts.join(' ')}`;
  }

  _invocation(opt) {
    if (opt.isHelp) return opt.flags.join(', ');
    return opt.flags.map((f) => `${f} ${opt.metavar}`).join(', ');
  }

  _formatHelp() {
    const indent = 2;
    const invocations = this._optionals.map((o) => this._invocation(o));
    // argparse: help_position = min(max_length_with_indent + 2, 24)
    const maxLen = Math.max(...invocations.map((s) => s.length + indent));
    const helpPos = Math.min(maxLen + 2, 24);
    const lines = [this._formatUsage(), '', 'options:'];
    for (let i = 0; i < this._optionals.length; i++) {
      const header = ' '.repeat(indent) + invocations[i];
      const help = this._optionals[i].help;
      if (help) {
        lines.push(header + ' '.repeat(helpPos - header.length) + help);
      } else {
        lines.push(header);
      }
    }
    return lines.join('\n');
  }

  _printHelpAndExit() {
    process.stdout.write(this._formatHelp() + '\n');
    process.exit(0);
  }

  error(message) {
    process.stderr.write(this._formatUsage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  _matchLong(name) {
    // Exact match first, then unambiguous prefix (argparse allow_abbrev).
    for (const opt of this._optionals) {
      if (opt.flags.includes(name)) return { opt };
    }
    const matches = [];
    for (const opt of this._optionals) {
      for (const f of opt.flags) {
        if (f.startsWith('--') && f.startsWith(name)) matches.push({ opt, flag: f });
      }
    }
    const uniqueOpts = [...new Set(matches.map((m) => m.opt))];
    if (uniqueOpts.length === 1) return { opt: uniqueOpts[0] };
    if (uniqueOpts.length > 1) {
      return { ambiguous: matches.map((m) => m.flag) };
    }
    return null;
  }

  parseArgs(argv = process.argv.slice(2)) {
    const values = {};
    for (const opt of this._optionals) {
      if (!opt.isHelp) values[opt.dest] = undefined;
    }
    const extras = [];
    const seen = new Set();

    let i = 0;
    while (i < argv.length) {
      const token = argv[i];
      if (token === '-h' || token === '--help') {
        this._printHelpAndExit();
      }
      if (token.startsWith('--') && token.length > 2) {
        const eq = token.indexOf('=');
        const name = eq === -1 ? token : token.slice(0, eq);
        const inlineValue = eq === -1 ? null : token.slice(eq + 1);
        const match = this._matchLong(name);
        if (match && match.ambiguous) {
          this.error(`ambiguous option: ${name} could match ${match.ambiguous.join(', ')}`);
        }
        if (!match) {
          extras.push(token);
          i += 1;
          continue;
        }
        const opt = match.opt;
        if (opt.isHelp) this._printHelpAndExit();
        let value;
        if (inlineValue !== null) {
          value = inlineValue;
        } else if (i + 1 < argv.length) {
          value = argv[i + 1];
          i += 1;
        } else {
          this.error(`argument ${opt.flags.join('/')}: expected one argument`);
        }
        values[opt.dest] = value;
        seen.add(opt.dest);
      } else if (token.startsWith('-') && token !== '-') {
        // Unknown short option.
        extras.push(token);
      } else {
        // No positionals are defined; anything positional is unrecognized.
        extras.push(token);
      }
      i += 1;
    }

    // parse_known_args raises the required-argument error first...
    const missing = this._optionals
      .filter((o) => !o.isHelp && o.required && !seen.has(o.dest))
      .map((o) => o.flags.find((f) => f.startsWith('--')) ?? o.flags[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    // ...then parse_args reports leftover unrecognized arguments.
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return values;
  }
}

