// Reimplementation of whoosh.analysis.StemmingAnalyzer (interface level).
// Only construction is exercised by the entry script; the token pipeline
// (tokenize -> lowercase -> stopword filter -> stem) mirrors the public shape.
export class StemmingAnalyzer {
  constructor() {
    // Default cache sizes used by whoosh's StemmingAnalyzer.
    this.cachesize = -1;
    this.stemfn = null;
  }
}

