// Reimplementation of the whoosh.fields pieces used by the entry script:
// TEXT field type and Schema (including its Python-style repr).

// Render an array of strings like Python's repr() of a list of str:
// ['content'] — single quotes, comma-space separators.
function pyListRepr(items) {
  return `[${items.map((s) => `'${s}'`).join(', ')}]`;
}

export class TEXT {
  constructor({ analyzer = null } = {}) {
    this.analyzer = analyzer;
  }
}

export class Schema {
  // Fields arrive as an object; key insertion order mirrors Python kwargs.
  constructor(fields = {}) {
    this._fields = { ...fields };
  }

  names() {
    return Object.keys(this._fields);
  }

  // whoosh Schema.__repr__: "<Schema: ['content']>"
  toString() {
    return `<Schema: ${pyListRepr(this.names())}>`;
  }
}

