// Entry point — mirrors /workspace/dataset/whoosh/test3.py.
import { ArgumentParser } from './lib/argparse.mjs';
import { Schema, TEXT } from './lib/fields.mjs';
import { StemmingAnalyzer } from './lib/analysis.mjs';

const parser = new ArgumentParser();
parser.addArgument(['--a'], { type: 'string', required: true });
const args = parser.parseArgs();

const analyzer = new StemmingAnalyzer(); // Create stemming analyzer
const schema = new Schema({ content: new TEXT({ analyzer }) }); // Create schema with custom analyzer
console.log(schema.toString());

